exif_content_remove_entry (ExifContent *c, ExifEntry *e)
{
        unsigned int i;
        ExifEntry **t, *temp;

        if (!c || !c->priv || !e || (e->parent != c)) return;

        /* Search the entry */
        for (i = 0; i < c->count; i++)
                        if (c->entries[i] == e)
                                        break;

        if (i == c->count)
                        return;

        /* Remove the entry */
        temp = c->entries[c->count-1];
        if (c->count > 1) {
                t = exif_mem_realloc (c->priv->mem, c->entries,
                                        sizeof(ExifEntry*) * (c->count - 1));
                if (!t) {
                        return;
                }
                c->entries = t;
                c->count--;
